import{_ as i,C as e,o as s,c as r,a2 as t,E as m}from"./chunks/framework.CCtxZRER.js";const b=JSON.parse('{"title":"Menghitung Min, Maks & ROP","description":"Menghitung stok minimum, stok maksimum, dan titik pemesanan ulang dengan rumus umum.","frontmatter":{"title":"Menghitung Min, Maks & ROP","description":"Menghitung stok minimum, stok maksimum, dan titik pemesanan ulang dengan rumus umum.","status":"draf","dasar":"rumus umum manajemen persediaan","catatan_status":"Materi Gudang Teknik menyebut perlunya perhitungan stok minimum, maksimum, dan ROP, tetapi belum memuat rumusnya. Rumus di sini adalah rumus umum. Parameter resmi seperti lead time dan stok pengaman mengikuti ketentuan gudang.","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Tutorial","tingkat":"Menengah","sumber":["ppt-gudang-teknik"],"kata_kunci":["tutorial","ROP","reorder point","stok minimum","stok maksimum","safety stock","lead time","pemakaian rata-rata","perhitungan stok"]},"headers":[],"relativePath":"tutorial/min-max-rop.md","filePath":"tutorial/min-max-rop.md"}'),l={name:"tutorial/min-max-rop.md"};function u(o,a,d,g,k,h){const n=e("MermaidDiagram");return s(),r("div",null,[a[0]||(a[0]=t('<h1 id="menghitung-min-maks-rop" tabindex="-1">Menghitung Min, Maks &amp; ROP <a class="header-anchor" href="#menghitung-min-maks-rop" aria-label="Permalink to &quot;Menghitung Min, Maks &amp; ROP&quot;">​</a></h1><p class="lead">Stock item perlu batas bawah, batas atas, dan titik kapan harus dipesan ulang. Tutorial ini memakai rumus umum yang banyak dipakai di pergudangan.</p><div class="tip custom-block"><p class="custom-block-title">Sebelum mulai</p><ul><li><strong>Setelah latihan ini, kamu bisa</strong> menghitung stok minimum, stok maksimum, dan ROP untuk satu material.</li><li><strong>Tingkat:</strong> Menengah, sekitar 30 menit.</li><li><strong>Baca dulu:</strong> <a href="/WareHouse/tutorial/fast-slow-moving">Menentukan Fast &amp; Slow Moving</a>.</li><li><strong>Siapkan:</strong> data pemakaian beberapa bulan terakhir, lead time pemesanan, kalkulator.</li></ul></div><h2 id="istilah-dan-rumus" tabindex="-1">Istilah dan rumus <a class="header-anchor" href="#istilah-dan-rumus" aria-label="Permalink to &quot;Istilah dan rumus&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Simbol</th><th>Arti</th><th>Rumus</th></tr></thead><tbody><tr><td data-label="Simbol"><strong>d</strong></td><td data-label="Arti">Pemakaian rata-rata per hari kerja</td><td data-label="Rumus">total pemakaian ÷ jumlah hari kerja</td></tr><tr><td data-label="Simbol"><strong>L</strong></td><td data-label="Arti">Lead time: hari dari pemesanan sampai barang tiba</td><td data-label="Rumus">dari data pembelian</td></tr><tr><td data-label="Simbol"><strong>SS</strong></td><td data-label="Arti">Safety stock (stok pengaman)</td><td data-label="Rumus">d × jumlah hari cadangan</td></tr><tr><td data-label="Simbol"><strong>ROP</strong></td><td data-label="Arti">Titik pemesanan ulang</td><td data-label="Rumus">(d × L) + SS</td></tr><tr><td data-label="Simbol"><strong>Min</strong></td><td data-label="Arti">Stok minimum</td><td data-label="Rumus">SS</td></tr><tr><td data-label="Simbol"><strong>Q</strong></td><td data-label="Arti">Jumlah sekali pesan</td><td data-label="Rumus">ditentukan gudang, misalnya mengikuti kemasan</td></tr><tr><td data-label="Simbol"><strong>Maks</strong></td><td data-label="Arti">Stok maksimum</td><td data-label="Rumus">SS + Q</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Konvensi bisa berbeda</p><p>Sebagian gudang menetapkan stok minimum sama dengan ROP, atau menghitung stok maksimum dengan cara lain. Pakai definisi yang berlaku di Gudang Teknik jika berbeda. Untuk <strong>critical stock</strong>, materi Gudang Teknik menetapkan stok minimum 1 unit.</p></div><h2 id="langkah-dengan-data-latihan" tabindex="-1">Langkah dengan data latihan <a class="header-anchor" href="#langkah-dengan-data-latihan" aria-label="Permalink to &quot;Langkah dengan data latihan&quot;">​</a></h2><p>Material latihan: <code>CTH-PPE-007</code> Sarung tangan kerja (fast moving).</p><ol><li><strong>Hitung pemakaian rata-rata per hari kerja.</strong> Total pemakaian 3 bulan adalah 132 pasang, dengan 66 hari kerja. d = 132 ÷ 66 = <strong>2 pasang/hari</strong></li><li><strong>Tentukan lead time.</strong> Dari data pembelian, barang biasanya tiba <strong>10 hari kerja</strong> setelah dipesan. L = 10.</li><li><strong>Hitung safety stock.</strong> Gudang ingin cadangan untuk <strong>5 hari</strong> jika pengiriman terlambat. SS = 2 × 5 = <strong>10 pasang</strong></li><li><strong>Hitung ROP.</strong> ROP = (2 × 10) + 10 = <strong>30 pasang</strong></li><li><strong>Tetapkan stok minimum.</strong> Min = SS = <strong>10 pasang</strong></li><li><strong>Tetapkan jumlah sekali pesan.</strong> Misalnya <strong>40 pasang</strong>, sesuai kemasan dari supplier.</li><li><strong>Hitung stok maksimum.</strong> Maks = 10 + 40 = <strong>50 pasang</strong></li></ol><h2 id="membaca-hasilnya" tabindex="-1">Membaca hasilnya <a class="header-anchor" href="#membaca-hasilnya" aria-label="Permalink to &quot;Membaca hasilnya&quot;">​</a></h2>',10)),m(n,{code:"flowchart%20LR%0A%20%20accTitle%3A%20Pergerakan%20stok%20sarung%20tangan%20latihan%0A%20%20accDescr%3A%20Stok%20turun%20dari%2050%20ke%2030%2C%20saat%20itu%20dipesan%2040.%20Selama%2010%20hari%20menunggu%2C%20stok%20turun%20ke%20sekitar%2010.%20Barang%20datang%20dan%20stok%20kembali%20ke%20sekitar%2050.%0A%20%20A%5BStok%2050%3Cbr%2F%3E%3D%20maksimum%5D%20--%20dipakai%202%2Fhari%20--%3E%20B%5BStok%2030%3Cbr%2F%3E%3D%20ROP%2C%20pesan%2040%5D%0A%20%20B%20--%20menunggu%2010%20hari%20--%3E%20C%5BStok%20%C2%B110%3Cbr%2F%3E%3D%20minimum%5D%0A%20%20C%20--%20barang%20datang%20%2B40%20--%3E%20D%5BStok%20%C2%B150%5D%0A"}),a[1]||(a[1]=t('<p>Saat stok turun ke <strong>30</strong>, gudang memesan <strong>40</strong>. Selama 10 hari menunggu, terpakai sekitar 20, sehingga stok tersisa sekitar <strong>10</strong> (stok pengaman) saat barang datang. Setelah barang diterima, stok kembali sekitar <strong>50</strong> (stok maksimum).</p><h2 id="kesalahan-umum" tabindex="-1">Kesalahan umum <a class="header-anchor" href="#kesalahan-umum" aria-label="Permalink to &quot;Kesalahan umum&quot;">​</a></h2><ul><li>Memakai hari kalender padahal pemakaian hanya terjadi di hari kerja, atau sebaliknya.</li><li>Lupa memperbarui angka saat pola pemakaian berubah, misalnya mesin baru dipasang.</li><li>Memakai lead time terlalu optimistis sehingga stok habis sebelum barang datang.</li></ul><h2 id="hasil-yang-diharapkan" tabindex="-1">Hasil yang diharapkan <a class="header-anchor" href="#hasil-yang-diharapkan" aria-label="Permalink to &quot;Hasil yang diharapkan&quot;">​</a></h2><p>Kamu bisa menghitung d, SS, ROP, stok minimum, dan stok maksimum untuk satu material, serta menjelaskan arti setiap angka kepada pembimbing.</p>',5))])}const c=i(l,[["render",u]]);export{b as __pageData,c as default};
